import test from 'node:test'
import assert from 'node:assert/strict'
import * as T from 'three'
import {Cinema,sequences} from '../src/karakurt/cinema.js'
import {Score} from '../src/karakurt/score.js'
const game=()=>({spider:{position:new T.Vector3(-6,0,4)},person:{position:new T.Vector3(5,0,0)},house:{probe:()=>null}})
test('All cinematic sequences finish once, skip safely and keep gameplay positions unchanged',()=>{
 for(const name of Object.keys(sequences)){
  const c=new Cinema(),g=game(),camera=new T.PerspectiveCamera();let ended=0;c.play(name,()=>ended++)
  for(let i=0;i<600&&c.active;i++){const f=c.update(.04,camera,g);assert.ok(camera.position.toArray().every(Number.isFinite));if(f)assert.ok(f.progress>=0&&f.progress<=1)}
  assert.equal(ended,1);c.finish();assert.equal(ended,1);assert.deepEqual(g.spider.position.toArray(),[-6,0,4])
  c.play(name,()=>ended++);c.finish();assert.equal(ended,2)
 }
})
test('Camera stops before room obstruction and memory subtitle is supplied by story',()=>{
 const c=new Cinema(),g=game(),camera=new T.PerspectiveCamera();g.house.probe=(origin,dir)=>origin.clone().addScaledVector(dir,.5)
 c.play('memory',()=>{},'Воспоминание');const f=c.update(.1,camera,g)
 assert.equal(f.text,'Воспоминание');assert.ok(camera.position.distanceTo(g.spider.position.clone().add(new T.Vector3(0,.2,0)))<.5)
})
test('Score schedules bounded polyphony, changes chords and stops all voices on pause',()=>{
 const voices=[];const param=()=>({value:0,setValueAtTime(){},linearRampToValueAtTime(){},exponentialRampToValueAtTime(){}})
 const context={currentTime:0,destination:{},createOscillator(){const o={frequency:param(),connect(){return this},start(){},stop(){this.stopped=true},disconnect(){}};voices.push(o);return o},createGain(){return {gain:param(),connect(){return this},disconnect(){}}}}
 const score=new Score(context);score.update(false,true);assert.equal(score.bar,1);assert.equal(voices.length,12)
