import test from 'node:test'
import assert from 'node:assert/strict'
import fs from 'node:fs'
import * as T from 'three'
import {parseTestGLB} from '../scripts/read-test-glb.js'
import {Karakurt} from '../src/karakurt/spider.js'
const items=Object.fromEntries(['Carapace','Abdomen','Marking'].map(n=>[n,new T.Group()]))
async function load(){return (await parseTestGLB(fs.readFileSync(new URL('../public/models/supplied-karakurt-ik.glb',import.meta.url)))).scene}
test('Supplied karakurt plants eight skinned feet on floor, wall and ceiling through movement and turns',async()=>{
 for(const normal of [new T.Vector3(0,1,0),new T.Vector3(1,0,0),new T.Vector3(0,-1,0)]){
  const spider=new Karakurt(items,await load()),probe=o=>o.clone().addScaledVector(normal,-o.dot(normal))
  spider.reset(new T.Vector3(),normal)
  for(let frame=0;frame<180;frame++){
   if(frame<100)spider.position.addScaledVector(spider.forward,.008);else spider.turn(.015)
   spider.update(1/60,frame<100,probe);spider.root.updateMatrixWorld(true)
   for(const c of spider.skin.chains){const tip=c.lower.localToWorld(new T.Vector3(0,c.b,0)),foot=spider.legs.find(l=>l.side===c.side&&l.i===c.i).foot;assert.ok(tip.distanceTo(foot)<.025,`foot ${c.side}/${c.i} misses by ${tip.distanceTo(foot)}`)}
  }
  assert.ok(spider.legs.every(l=>l.steps>0))
  const abdomen=spider.body.getObjectByName('Abdomen'),rest=abdomen.quaternion.clone();spider.cast=.9;spider.update(.04,false,probe);assert.ok(abdomen.quaternion.angleTo(rest)>.001)
  assert.ok(spider.leap());for(let f=0;f<100;f++)spider.update(1/60,false,probe)
  assert.equal(spider.jump,0)
 }
})
test('Supplied karakurt has normalized skin weights and visibly deforming mesh',async()=>{
 const model=await load(),spider=new Karakurt(items,model);let mesh;model.traverse(n=>{if(n.isSkinnedMesh)mesh=n})
 assert.ok(mesh);assert.equal(mesh.skeleton.bones.length,18)
 const w=mesh.geometry.attributes.skinWeight;for(let i=0;i<w.count;i++)assert.ok(Math.abs(w.getX(i)+w.getY(i)+w.getZ(i)+w.getW(i)-1)<1e-5)
 const sample=()=>{spider.root.updateMatrixWorld(true);mesh.skeleton.update();return Array.from({length:mesh.geometry.attributes.position.count},(_,i)=>mesh.getVertexPosition(i,new T.Vector3()))},probe=o=>new T.Vector3(o.x,0,o.z)
 spider.update(1/60,false,probe);const rest=sample();for(let f=0;f<40;f++){spider.position.z-=.012;spider.update(1/60,true,probe)}
 const moved=sample();assert.ok(moved.every(p=>Number.isFinite(p.length())));assert.ok(moved.filter((p,i)=>p.distanceTo(rest[i])>.02).length>100)
})
